from fai.consts import START_CODON_OFFSET, STOP_CODON_OFFSET
from fai.contracts import Read
from fai.logic import add_flankers_to_reads, calculate_deltas_by_subset


def test_calculate_deltas_by_subset_size():
    gene_dict = {
        "gene1": "",  # noqa: E501
        "gene2": "",  # noqa: E501
        "gene3": "",  # noqa: E501
        "gene4": "CGTATGCGCAGAATGTGGGAATGCCAATTATAGGGGTGCCGAGGTGCCTTATAAAACCCTTTTCTGTGCCTGTGACATTTCCTTTTTCGGTCAAAAAGAATATCCGAATTTTAGATTTGGACCCTCGTACAGAAGCTTATTGTCTAAGCCTGAATTCAGTCTGCTTTAAACGGCTTCCGCGGAGGAAATATTTCCATCTCTTGAATTCGTACAACATTAAACGTGTGTTGGGAGTCGTATACTGTTAGGGTCTGTAAACTTGTGAACT",  # noqa: E501
        "gene5": "",  # noqa: E501
        "gene6": "",  # noqa: E501
        "gene7": "",  # noqa: E501
        "gene8": "",  # noqa: E501
        "gene9": "",  # noqa: E501
        "gene10": "",  # noqa: E501
        "gene12": "",  # noqa: E501
        "gene13": "",  # noqa: E501
        "gene14": "",  # noqa: E501
        "gene15": "",  # noqa: E501
        "gene16": "",  # noqa: E501
        "gene17": "",  # noqa: E501
        "gene18": "",  # noqa: E501
        "gene19": "",  # noqa: E501
        "gene20": "",  # noqa: E501
        "gene21": "",  # noqa: E501
        "gene22": "",  # noqa: E501
        "gene23": "",  # noqa: E501
        "gene24": "",  # noqa: E501
    }

    size_seeds = [
        {
            "size": 25,
            "base_delta": 12,
        },
        {
            "size": 26,
            "base_delta": 13,
        },
        {
            "size": 27,
            "base_delta": 14,
        },
        {
            "size": 28,
            "base_delta": 15,
        },
        {
            "size": 29,
            "base_delta": 16,
        },
    ]

    reads_spacing = 3

    reads_with_deltas_by_size = [
        Read(
            gene,
            START_CODON_OFFSET + offset * reads_spacing - delta + 1,
            read_size,
        )
        for delta, read_size in [
            (seed["base_delta"], seed["size"]) for seed in size_seeds
        ]
        for gene in gene_dict
        for offset in range(
            0,
            (len(gene_dict[gene]) - START_CODON_OFFSET - STOP_CODON_OFFSET)
            // reads_spacing,
        )
    ]

    reads_with_flankers = add_flankers_to_reads(reads_with_deltas_by_size, gene_dict)

    deltas_by_subset = calculate_deltas_by_subset(reads_with_flankers, gene_dict)

    expected_deltas = {
        f"{size}:F{flanker}:{nt}": delta
        for delta, size in [[seed["base_delta"], seed["size"]] for seed in size_seeds]
        for flanker in range(8)
        for nt in ["A", "T", "C", "G"]
    }

    assert deltas_by_subset == expected_deltas


def test_fail_if_reads_with_not_flankers():
    gene_dict = {
        "gene1": "",  # noqa: E501
        "gene2": "",  # noqa: E501
        "gene3": "",  # noqa: E501
    }

    reads_spacing = 3
    delta = 17
    min_size = 25
    max_size = 35

    reads = [
        Read(
            gene,
            START_CODON_OFFSET + offset * reads_spacing - delta - 1,
            size,
        )
        for size in range(min_size, max_size + 1)
        for gene in gene_dict
        for offset in range(
            0,
            (len(gene_dict[gene]) - START_CODON_OFFSET - STOP_CODON_OFFSET)
            // reads_spacing,
        )
    ]

    try:
        calculate_deltas_by_subset(reads, gene_dict)
    except ValueError as e:
        assert str(e) == "All reads must have flankers"
    else:
        assert False, "Expected ValueError was not raised"
